import { useEffect, useMemo, useState } from 'react'
import {
  Activity, Apple, ArrowDownRight, ArrowRight, Bell, CalendarDays,
  Check, ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, Clock3,
  Dumbbell, Ellipsis, FileText, Filter, LayoutDashboard, LogOut, Menu, Plus,
  Search, ShieldCheck, SlidersHorizontal, Sparkles, Users, X,
} from 'lucide-react'
import { hasSupabaseConfig, supabase } from './lib/supabase'
import StudentDetail from './components/StudentDetail'

const navItems = [
  { label:'Genel Bakış', icon:LayoutDashboard }, { label:'Öğrenciler', icon:Users },
  { label:'Antrenman', icon:Dumbbell }, { label:'Beslenme', icon:Apple },
  { label:'Gelişim', icon:Activity }, { label:'Takvim', icon:CalendarDays },
  { label:'Finans', icon:CircleDollarSign },
]
const money = value => new Intl.NumberFormat('tr-TR', { style:'currency', currency:'TRY', maximumFractionDigits:0 }).format(Number(value || 0))
const localDate = () => {const date=new Date();date.setMinutes(date.getMinutes()-date.getTimezoneOffset());return date.toISOString().slice(0,10)}
const localDateOffset = days => {const date=new Date();date.setDate(date.getDate()-days);date.setMinutes(date.getMinutes()-date.getTimezoneOffset());return date.toISOString().slice(0,10)}
const initials = name => (name || '').split(' ').map(x=>x[0]).slice(0,2).join('').toLocaleUpperCase('tr-TR')
const fmtDate = value => value ? new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short'}).format(new Date(value+'T12:00:00')) : '—'
const ageOf = value => {if(!value)return null;const born=new Date(`${value}T12:00:00`);const now=new Date();let age=now.getFullYear()-born.getFullYear();if(now.getMonth()<born.getMonth()||(now.getMonth()===born.getMonth()&&now.getDate()<born.getDate()))age--;return age>=0?age:null}
const todayLabel = new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',weekday:'long'}).format(new Date()).toLocaleUpperCase('tr-TR')
const todayShort = new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',weekday:'long'}).format(new Date()).toLocaleUpperCase('tr-TR')
const studentProgress = student => {
  const start=Number(student.start_weight), current=Number(student.current_weight_kg), target=Number(student.target_weight)
  if(!start||!current||!target||start===target)return null
  return Math.max(0,Math.min(100,Math.round(((start-current)/(start-target))*100)))
}

export default function App(){
  const [session, setSession] = useState(null)
  const [profile, setProfile] = useState(null)
  const [authReady, setAuthReady] = useState(!hasSupabaseConfig)
  const [recoveryMode, setRecoveryMode] = useState(false)
  const [students, setStudents] = useState([])
  const [payments, setPayments] = useState([])
  const [appointments, setAppointments] = useState([])
  const [workoutLogs, setWorkoutLogs] = useState([])
  const [nutritionLogs, setNutritionLogs] = useState([])
  const [nutritionPlans, setNutritionPlans] = useState([])
  const [studentReports, setStudentReports] = useState([])
  const [measurements, setMeasurements] = useState([])
  const [loading, setLoading] = useState(false)
  const [activePage, setActivePage] = useState('Genel Bakış')
  const [search, setSearch] = useState('')
  const [period, setPeriod] = useState('Bu ay')
  const [showAdd, setShowAdd] = useState(false)
  const [recordKind, setRecordKind] = useState('')
  const [selectedStudent, setSelectedStudent] = useState(null)
  const [notice, setNotice] = useState('')
  const [mobileNav, setMobileNav] = useState(false)

  useEffect(()=>{
    if(!supabase){
      setStudents([])
      setPayments([])
      setAppointments([])
      setWorkoutLogs([]);setNutritionLogs([]);setNutritionPlans([]);setStudentReports([]);setMeasurements([])
      return
    }
    let alive = true
    supabase.auth.getSession().then(({data})=>{ if(alive){ setSession(data.session); setAuthReady(true) } })
    const {data:{subscription}} = supabase.auth.onAuthStateChange((event,next)=>{
      if(event === 'PASSWORD_RECOVERY') setRecoveryMode(true)
      setSession(next)
      setAuthReady(true)
    })
    return ()=>{ alive=false; subscription.unsubscribe() }
  },[])

  useEffect(()=>{
    if(!supabase || !session) return
    let alive=true
    setLoading(true)
    const load = async()=>{
      const [{data:pr,error:prError},{data:st,error:stError},{data:pay,error:payError},{data:ap,error:apError},{data:wl,error:wlError},{data:nl,error:nlError},{data:np,error:npError},{data:sr,error:srError},{data:me,error:meError}] = await Promise.all([
        supabase.from('profiles').select('full_name,role,avatar_url').eq('id',session.user.id).single(),
        supabase.from('students').select('*').order('created_at',{ascending:false}),
        supabase.from('payments').select('id,student_id,description,amount,status,due_date,paid_at,created_at,students(full_name)').order('created_at',{ascending:false}).limit(1000),
        supabase.from('appointments').select('id,student_id,starts_at,ends_at,status,location,notes,students(full_name)').gte('starts_at',new Date(Date.now()-30*86400000).toISOString()).order('starts_at',{ascending:true}).limit(100),
        supabase.from('workout_logs').select('id,student_id,completed,completed_at,exercise_results,students(full_name)').order('completed_at',{ascending:false}).limit(300),
        supabase.from('nutrition_logs').select('id,student_id,logged_on,meals_completed,water_ml,students(full_name)').gte('logged_on',localDateOffset(7)).order('logged_on',{ascending:false}).limit(1000),
        supabase.from('nutrition_plans').select('student_id,meal_count').eq('active',true),
        supabase.from('student_reports').select('id,student_id,report_date,reviewed_at,energy_level,nutrition_adherence,students(full_name)').order('report_date',{ascending:false}).limit(100),
        supabase.from('measurements').select('id,student_id,measured_on,weight_kg').order('measured_on',{ascending:false}).limit(500),
      ])
      if(!alive)return
      if(prError){setNotice(prError.message);setProfile(null)} else setProfile(pr)
      if(!stError){const latestByStudent=new Map();for(const row of me||[])if(!latestByStudent.has(row.student_id))latestByStudent.set(row.student_id,row);setStudents((st||[]).map(student=>({...student,current_weight_kg:latestByStudent.get(student.id)?.weight_kg??student.current_weight_kg})))} else setNotice(stError.message)
      if(!payError)setPayments((pay||[]).map(p=>({id:p.id,name:p.students?.full_name||'Öğrenci',date:p.due_date?fmtDate(p.due_date):'—',description:p.description,amount:p.amount,status:p.status,paid_at:p.paid_at,created_at:p.created_at,initials:initials(p.students?.full_name||''),color:'mint'})))
      if(!apError)setAppointments((ap||[]).map(a=>({id:a.id,student_id:a.student_id,starts_at:a.starts_at,ends_at:a.ends_at,location:a.location,time:new Date(a.starts_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'}),date:new Date(a.starts_at).toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'}),name:a.students?.full_name||'Öğrenci',type:a.notes||'Özel antrenman',status:a.status,initials:initials(a.students?.full_name||''),color:'peach'})))
      if(!wlError)setWorkoutLogs(wl||[]);if(!nlError)setNutritionLogs(nl||[]);if(!npError)setNutritionPlans(np||[]);if(!srError)setStudentReports(sr||[]);if(!meError)setMeasurements(me||[])
      setLoading(false)
    }
    load()
    return ()=>{alive=false}
  },[session])

  useEffect(()=>{ if(!notice)return; const t=setTimeout(()=>setNotice(''),4500); return ()=>clearTimeout(t) },[notice])

  const activeStudents = students.filter(s=>s.status==='active').length
  const pendingStudents = students.filter(s=>s.status==='pending').length
  const visibleStudents = useMemo(()=>students.filter(s=>`${s.full_name} ${s.email||''} ${s.goal||''}`.toLocaleLowerCase('tr-TR').includes(search.toLocaleLowerCase('tr-TR'))),[students,search])
  const dueTotal = payments.filter(p=>p.status==='pending'||p.status==='overdue').reduce((n,p)=>n+Number(p.amount||0),0)
  const receivedTotal = payments.filter(p=>p.status==='paid').reduce((n,p)=>n+Number(p.amount||0),0)

  async function createStudent(form){
    const record={...form, status:'active', joined_on:localDate()}
    if(!supabase){setNotice('Öğrenci kaydetmek için Supabase bağlantısı gerekli.');return}
    const {data,error}=await supabase.from('students').insert(record).select().single()
    if(error){setNotice(error.message);return}
    setStudents([data,...students])
    setShowAdd(false)
  }

  async function approveStudent(student){
    const {data,error}=await supabase.from('students').update({status:'active'}).eq('id',student.id).select().single()
    if(error){setNotice(`Öğrenci onaylanamadı: ${error.message}`);return}
    setStudents(current=>current.map(item=>item.id===data.id?data:item))
    setNotice(`${student.full_name} aktif öğrenci olarak onaylandı.`)
  }

  async function saveRecord(form){
    if(!supabase){setNotice('Kayıt oluşturmak için Supabase bağlantısı gerekli.');return}
    if(recordKind==='appointment'){
      const starts_at=new Date(form.starts_at).toISOString();const ends_at=form.ends_at?new Date(form.ends_at).toISOString():null
      const {data,error}=await supabase.from('appointments').insert({student_id:form.student_id,starts_at,ends_at,location:form.location||null,notes:form.notes||null,status:'scheduled'}).select('id,student_id,starts_at,ends_at,status,location,notes,students(full_name)').single()
      if(error){setNotice(error.message);return}
      setAppointments(rows=>[...rows,{id:data.id,student_id:data.student_id,starts_at:data.starts_at,ends_at:data.ends_at,location:data.location,time:new Date(data.starts_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'}),date:new Date(data.starts_at).toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'}),name:data.students?.full_name||'Öğrenci',type:data.notes||'Özel antrenman',status:data.status,initials:initials(data.students?.full_name||''),color:'peach'}].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)))
    }else{
      const {data,error}=await supabase.from('payments').insert({student_id:form.student_id,description:form.description||'PT paketi',amount:Number(form.amount),status:form.status,due_date:form.due_date||null,paid_at:form.status==='paid'?new Date().toISOString():null}).select('id,student_id,description,amount,status,due_date,paid_at,created_at,students(full_name)').single()
      if(error){setNotice(error.message);return}
      setPayments(rows=>[{id:data.id,name:data.students?.full_name||'Öğrenci',date:data.due_date?fmtDate(data.due_date):'—',description:data.description,amount:data.amount,status:data.status,paid_at:data.paid_at,created_at:data.created_at,initials:initials(data.students?.full_name||''),color:'mint'},...rows])
    }
    setRecordKind('');setNotice(recordKind==='appointment'?'Seans takvime eklendi.':'Ödeme kaydı oluşturuldu.')
  }

  async function updateAppointment(item,status){const {error}=await supabase.from('appointments').update({status}).eq('id',item.id);if(error){setNotice(error.message);return}setAppointments(rows=>rows.map(row=>row.id===item.id?{...row,status}:row));setNotice(status==='completed'?'Seans tamamlandı olarak işaretlendi.':'Seans iptal edildi.')}
  async function updatePayment(item,status){const {error}=await supabase.from('payments').update({status,paid_at:status==='paid'?new Date().toISOString():null}).eq('id',item.id);if(error){setNotice(error.message);return}setPayments(rows=>rows.map(row=>row.id===item.id?{...row,status,paid_at:status==='paid'?new Date().toISOString():null}:row));setNotice(status==='paid'?'Ödeme tahsil edildi olarak kaydedildi.':'Ödeme bekliyor olarak güncellendi.')}

  async function signOut(){ if(supabase) await supabase.auth.signOut(); setSession(null); setProfile(null) }

  if(hasSupabaseConfig && recoveryMode) return <PasswordRecovery onComplete={()=>setRecoveryMode(false)} />
  if(hasSupabaseConfig && !authReady) return <div className="loading-screen"><span className="loader"/>Oturum kontrol ediliyor…</div>
  if(hasSupabaseConfig && !session) return <LoginScreen />
  if(hasSupabaseConfig && session && profile && profile.role!=='admin') return <StudentView user={session.user} profile={profile} onSignOut={signOut} />
  if(hasSupabaseConfig && session && !profile) return <div className="loading-screen"><div className="setup-card"><ShieldCheck size={26}/><h2>Hesap erişimi bekleniyor</h2><p>Hesabınız henüz bir PT profiline bağlanmadı. Emre yöneticiyse Supabase profiles tablosunda rolü admin olarak ayarlanmalı. Öğrenci erişimi için profil, öğrenci kaydıyla eşleştirilmelidir.</p><button className="btn-primary" onClick={signOut}>Çıkış yap</button></div></div>

  return <div className="app-shell">
    {mobileNav&&<button aria-label="Menüyü kapat" className="mobile-scrim" onClick={()=>setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav?'sidebar-open':''}`}>
      <div className="brand"><div className="brand-mark"><Activity size={20}/></div><div><strong>EMRE AKKOYUN</strong><span>PERSONAL TRAINER</span></div><button className="icon-btn mobile-close" onClick={()=>setMobileNav(false)}><X size={17}/></button></div>
      <div className="workspace-label">ÇALIŞMA ALANI</div>
      <nav className="nav-list">{navItems.map(({label,icon:Icon})=><button key={label} className={`nav-item ${activePage===label?'active':''}`} onClick={()=>{setActivePage(label);setMobileNav(false)}}><Icon size={18}/><span>{label}</span>{label==='Öğrenciler'&&<em>{students.length}</em>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="coach-card"><div className="coach-icon"><Sparkles size={17}/></div><strong>Bir sonraki seviyeye</strong><p>Öğrenci gelişimini düzenli ölçümle takip et.</p><button onClick={()=>setActivePage('Gelişim')}>Gelişim raporları <ArrowRight size={14}/></button></div><div className="user-mini"><div className="avatar avatar-coach">EA</div><div className="user-label"><strong>{profile?.full_name||'Emre Akkoyun'}</strong><span>{profile?.role==='admin'?'Yönetici':'PT Koçu'}</span></div><button className="icon-btn" title="Oturumu kapat" onClick={signOut}><LogOut size={16}/></button></div></div>
    </aside>
    <main className="main-content">
      <header className="topbar"><button className="icon-btn menu-toggle" onClick={()=>setMobileNav(true)} aria-label="Menüyü aç"><Menu size={20}/></button><div className="breadcrumb"><span>PT Yönetimi</span><ChevronRight size={14}/><strong>{activePage}</strong></div><div className="topbar-right"><span className={`connection ${hasSupabaseConfig?'connected':''}`}><i/>{hasSupabaseConfig?'Supabase bağlı':'Önizleme modu'}</span><button className="icon-btn notification-btn" aria-label="Bildirimler"><Bell size={18}/><i/></button><div className="avatar avatar-coach top-avatar">EA</div></div></header>
      <div className="page-wrap">
        <div className="welcome-row"><div><div className="eyebrow">{todayLabel}</div><h1>{activePage==='Genel Bakış'?`Günaydın, ${profile?.full_name?.split(' ')[0]||'Emre'}`:activePage}<span className="wave">{activePage==='Genel Bakış'?' ☀':''}</span></h1><p>{activePage==='Genel Bakış'?'Bugün öğrencilerin için güzel bir gün. İşte stüdyondaki son durum.':'Öğrenci süreçlerini tek yerden takip et ve yönet.'}</p></div><div className="welcome-actions"><button className="btn-quiet" onClick={()=>setNotice('Rapor özeti hazır olduğunda burada görüntülenecek.')}><FileText size={16}/> Rapor al</button><button className="btn-primary" onClick={()=>setShowAdd(true)}><Plus size={17}/> Öğrenci ekle</button></div></div>
        {!hasSupabaseConfig&&<div className="demo-banner"><div><ShieldCheck size={16}/><span><strong>Supabase bağlantısı gerekli:</strong> gerçek öğrenci verileri için uygulama ortamı yapılandırılmalı.</span></div></div>}
        {notice&&<div className="toast"><Check size={16}/>{notice}<button onClick={()=>setNotice('')}><X size={15}/></button></div>}
        {activePage==='Öğrenciler'?<StudentsPage students={visibleStudents} query={search} setQuery={setSearch} onAdd={()=>setShowAdd(true)} onApprove={approveStudent} onOpen={setSelectedStudent}/>:activePage==='Genel Bakış'?<Dashboard students={students} activeStudents={activeStudents} pendingStudents={pendingStudents} payments={payments} appointments={appointments.filter(a=>new Date(a.starts_at).toDateString()===new Date().toDateString())} workoutLogs={workoutLogs} nutritionLogs={nutritionLogs} nutritionPlans={nutritionPlans} studentReports={studentReports} measurements={measurements} receivedTotal={receivedTotal} dueTotal={dueTotal} period={period} setPeriod={setPeriod} loading={loading} onOpenStudents={()=>setActivePage('Öğrenciler')} onOpenCalendar={()=>setActivePage('Takvim')} onOpenFinances={()=>setActivePage('Finans')}/>:<ModulePage page={activePage} students={students} appointments={appointments} payments={payments} onAdd={()=>activePage==='Takvim'?setRecordKind('appointment'):activePage==='Finans'?setRecordKind('payment'):setActivePage('Öğrenciler')} onNotice={setNotice} onOpenStudent={student=>setSelectedStudent(student)} onUpdateAppointment={updateAppointment} onUpdatePayment={updatePayment}/>}
      </div>
      <footer className="footer"><span>© 2026 Emre Akkoyun PT Management</span><span><i/> Tüm sistemler çalışıyor</span></footer>
    </main>
    {showAdd&&<AddStudentModal onClose={()=>setShowAdd(false)} onSave={createStudent}/>}
    {recordKind&&<RecordModal kind={recordKind} students={students.filter(s=>s.status!=='inactive')} onClose={()=>setRecordKind('')} onSave={saveRecord}/>}
    {selectedStudent&&<StudentDetail student={selectedStudent} onClose={()=>setSelectedStudent(null)} onChanged={student=>{setSelectedStudent(student);setStudents(current=>current.map(item=>item.id===student.id?student:item))}}/>}
  </div>
}

function LoginScreen(){
  const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [fullName,setFullName]=useState(''); const [registering,setRegistering]=useState(false); const [working,setWorking]=useState(false); const [error,setError]=useState(''); const [info,setInfo]=useState('')
  async function submit(e){e.preventDefault();setWorking(true);setError('');setInfo('');if(registering){const redirectTo=`${window.location.origin}${window.location.pathname}`;const {data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name:fullName.trim()},emailRedirectTo:redirectTo}});if(error)setError(error.message);else setInfo(data.session?'Kaydın alındı. Yönetici onayından sonra hesabın açılacak.':'Doğrulama bağlantısı e-posta adresine gönderildi. E-postanı doğruladıktan sonra giriş yap; hesabın yönetici onayı bekleyecek.')}else{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)setError(error.message)}setWorking(false)}
  async function reset(){if(!email){setError('Önce e-posta adresini yaz.');return}setWorking(true);const redirectTo=`${window.location.origin}${window.location.pathname}`;const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo});setError(error?error.message:'Şifre belirleme bağlantısı e-posta adresine gönderildi.');setWorking(false)}
  return <div className="login-page"><div className="login-visual"><div className="brand"><div className="brand-mark"><Activity size={20}/></div><div><strong>EMRE AKKOYUN</strong><span>PERSONAL TRAINER</span></div></div><div className="login-art"><div className="art-orbit orbit-one"/><div className="art-orbit orbit-two"/><div className="art-sun"/><Activity size={220} strokeWidth={0.7}/><span>STRENGTH<br/>IN EVERY<br/>STEP.</span></div><div className="login-caption"><span>01 / 03</span><p>Her hedef, doğru<br/>planla başlar.</p></div></div><div className="login-form-wrap"><form className="login-form" onSubmit={submit}><div className="eyebrow">{registering?'ÖĞRENCİ KAYDI':'HOŞ GELDİN'}</div><h1>{registering?'Hesap oluştur':'Hesabına giriş yap'}</h1><p>{registering?'Antrenörünle çalışmaya başlamak için bilgilerini gir.':'Antrenman yolculuğuna kaldığın yerden devam et.'}</p>{registering&&<label>Ad soyad<input value={fullName} onChange={e=>setFullName(e.target.value)} placeholder="Adın ve soyadın" required autoComplete="name"/></label>}<label>E-posta adresi<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="ornek@email.com" required autoComplete="email"/></label><label>Şifre<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="En az 8 karakter" required minLength={8} autoComplete={registering?'new-password':'current-password'}/></label>{error&&<div className="form-error">{error}</div>}{info&&<div className="form-info">{info}</div>}<button className="btn-primary login-submit" disabled={working}>{working?(registering?'Hesap oluşturuluyor…':'Giriş yapılıyor…'):(registering?'Kayıt ol':'Giriş yap')} <ArrowRight size={16}/></button>{!registering&&<button type="button" className="text-link" onClick={reset}>Şifremi unuttum</button>}<button type="button" className="text-link auth-toggle" onClick={()=>{setRegistering(v=>!v);setError('');setInfo('')}}>{registering?'Zaten hesabın var mı? Giriş yap':'Yeni öğrenci misin? Hesap oluştur'}</button><div className="secure-note"><ShieldCheck size={15}/> Hesabın güvenli Supabase girişiyle korunuyor.</div></form><div className="login-footer">© 2026 Emre Akkoyun <span>·</span> Gizlilik ve kullanım</div></div></div>
}

function PasswordRecovery({onComplete}){
  const [password,setPassword]=useState('')
  const [confirm,setConfirm]=useState('')
  const [working,setWorking]=useState(false)
  const [error,setError]=useState('')
  const [saved,setSaved]=useState(false)
  async function submit(e){
    e.preventDefault(); setError('')
    if(password.length<8){setError('Şifren en az 8 karakter olmalı.');return}
    if(password!==confirm){setError('Şifreler eşleşmiyor.');return}
    setWorking(true)
    const {error:saveError}=await supabase.auth.updateUser({password})
    if(saveError)setError(saveError.message);else setSaved(true)
    setWorking(false)
  }
  return <div className="recovery-page"><div className="recovery-brand"><div className="brand-mark"><Activity size={20}/></div><div><strong>EMRE AKKOYUN</strong><span>PERSONAL TRAINER</span></div></div><form className="recovery-card" onSubmit={submit}><div className="eyebrow">HESAP GÜVENLİĞİ</div><h1>Yeni şifreni belirle</h1><p>Belirleyeceğin şifreyle masaüstü ve mobil cihazlardan giriş yapabilirsin.</p>{!saved?<><label>Yeni şifre<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="En az 8 karakter" minLength={8} required autoComplete="new-password"/></label><label>Şifreyi tekrar yaz<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Yeni şifreni doğrula" required autoComplete="new-password"/></label>{error&&<div className="form-error">{error}</div>}<button className="btn-primary recovery-submit" disabled={working}>{working?'Kaydediliyor…':'Şifreyi kaydet'} <ArrowRight size={16}/></button></>:<><div className="recovery-success"><Check size={17}/> Şifren kaydedildi. Artık mobil ve masaüstünde kullanabilirsin.</div><button type="button" className="btn-primary recovery-submit" onClick={onComplete}>Uygulamaya geç <ArrowRight size={16}/></button></>}</form><div className="recovery-footer">© 2026 Emre Akkoyun PT Management</div></div>
}

function Dashboard({students,activeStudents,pendingStudents,payments,appointments,workoutLogs,nutritionLogs,nutritionPlans,studentReports,measurements,receivedTotal,dueTotal,period,setPeriod,loading,onOpenStudents,onOpenCalendar,onOpenFinances}){
 const currentWeekStart=new Date();currentWeekStart.setHours(0,0,0,0);currentWeekStart.setDate(currentWeekStart.getDate()-((currentWeekStart.getDay()+6)%7))
 const weeklyIncome=Array.from({length:12},(_,index)=>{const start=new Date(currentWeekStart);start.setDate(start.getDate()-(11-index)*7);const end=new Date(start);end.setDate(end.getDate()+7);const amount=payments.filter(p=>p.status==='paid'&&(p.paid_at||p.created_at)&&new Date(p.paid_at||p.created_at)>=start&&new Date(p.paid_at||p.created_at)<end).reduce((sum,p)=>sum+Number(p.amount||0),0);return{start,amount}})
 const max=Math.max(1,...weeklyIncome.map(w=>w.amount))
 const hasWeeklyIncome=weeklyIncome.some(w=>w.amount>0)
 const weekAgo=new Date(Date.now()-7*86400000)
 const weeklyWorkouts=workoutLogs.filter(log=>log.completed&&new Date(log.completed_at)>=weekAgo).length
 const weeklyNutrition=nutritionLogs.filter(log=>new Date(`${log.logged_on}T23:59:59`)>weekAgo)
 const trackedMeals=weeklyNutrition.reduce((sum,log)=>sum+(log.meals_completed||[]).length,0)
 const plannedMeals=weeklyNutrition.reduce((sum,log)=>sum+(Number(nutritionPlans.find(plan=>plan.student_id===log.student_id)?.meal_count)||0),0)
 const nutritionAdherence=plannedMeals?Math.min(100,Math.round(trackedMeals/plannedMeals*100)):null
 const reportsToReview=studentReports.filter(report=>!report.reviewed_at).length
 const latestByStudent=new Map();for(const measurement of measurements){if(!latestByStudent.has(measurement.student_id))latestByStudent.set(measurement.student_id,measurement)}
 const measurementsDue=students.filter(student=>student.status==='active'&&(!latestByStudent.has(student.id)||new Date(latestByStudent.get(student.id).measured_on)<weekAgo)).length
 const weekdays=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];
 return <>
  <section className="stats-grid">
   <StatCard icon={Users} label="Toplam öğrenci" value={String(students.length).padStart(2,'0')} note={<><span className="neutral-pill">{activeStudents} aktif</span><span>öğrenci kaydı</span></>} tone="mint"/>
   <StatCard icon={Users} label="Onay bekleyen" value={String(pendingStudents).padStart(2,'0')} note={<><span className="neutral-pill">Yeni kayıt</span><span>inceleme gerekiyor</span></>} tone="lavender"/>
   <StatCard icon={CircleDollarSign} label="Toplam tahsilat" value={money(receivedTotal)} note={<><span className="neutral-pill">{payments.filter(p=>p.status==='paid').length} kayıt</span><span>{receivedTotal?'tahsil edildi':'henüz tahsilat yok'}</span></>} tone="gold"/>
   <StatCard icon={CalendarDays} label="Bugünkü seanslar" value={String(appointments.length).padStart(2,'0')} note={<><span className="neutral-pill">{appointments.filter(a=>a.status==='completed').length} tamamlandı</span></>} tone="lavender"/>
   <StatCard icon={Clock3} label="Bekleyen ödeme" value={money(dueTotal)} note={<><span className={dueTotal?'down-pill':'neutral-pill'}>{dueTotal?'Takip et':'0 kayıt'}</span><span>{dueTotal?'ödenmemiş bakiye':'bekleyen borç yok'}</span></>} tone="rose"/>
  </section>
  <section className="overview-grid">
   <div className="panel growth-panel"><div className="panel-head"><div><div className="panel-kicker">GENEL PERFORMANS</div><h2>Gelir görünümü</h2><p>Son 12 haftadaki tahsilatların</p></div><button className="select-btn" onClick={()=>setPeriod(period==='Bu ay'?'Son 3 ay':'Bu ay')}>{period}<ChevronDown size={14}/></button></div><div className="chart-summary"><strong>{money(receivedTotal)}</strong><span className="chart-change"><CircleDollarSign size={14}/>{payments.filter(p=>p.status==='paid').length} tahsilat</span></div>{hasWeeklyIncome?<><div className="chart"><div className="chart-y"><span>{money(max)}</span><span>{money(max*2/3)}</span><span>{money(max/3)}</span><span>₺0</span></div><div className="chart-area"><div className="chart-gridlines"><i/><i/><i/><i/></div><div className="bars">{weeklyIncome.map((week,i)=><div className="bar-col" key={i}><span className="bar" style={{height:`${Math.max(5,week.amount/max*90)}%`}}/><span className="bar-label">{week.start.toLocaleDateString('tr-TR',{month:'short',day:'numeric'})}</span></div>)}</div></div></div><div className="chart-legend"><span><i className="legend-dot current"/>Haftalık tahsilat</span></div></>:<div className="revenue-empty"><div className="empty-illustration"><CircleDollarSign size={24}/></div><strong>Henüz gelir kaydı yok</strong><span>Ödeme eklediğinde tahsilat grafiğin burada oluşacak.</span></div>}</div>
   <div className="panel appointments-panel"><div className="panel-head compact"><div><div className="panel-kicker">{todayShort}</div><h2>Günün seansları</h2></div><button className="icon-btn" onClick={onOpenCalendar} aria-label="Takvimi aç"><ArrowRight size={17}/></button></div><div className="date-strip"><button aria-label="Önceki gün" onClick={onOpenCalendar}><ChevronLeft size={16}/></button>{Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i-3);return <button className={i===3?'selected':''} key={d.toISOString()} onClick={i===3?undefined:onOpenCalendar}><span>{new Intl.DateTimeFormat('tr-TR',{weekday:'short'}).format(d)}</span><b>{d.getDate()}</b></button>})}<button aria-label="Sonraki gün" onClick={onOpenCalendar}><ChevronRight size={16}/></button></div><div className="appointment-list">{appointments.slice(0,4).map(a=><AppointmentRow key={a.id} item={a}/>)}</div><button className="panel-link" onClick={onOpenCalendar}>Tüm takvimi görüntüle <ArrowRight size={14}/></button></div>
  </section>
  <section className="bottom-grid"><div className="panel students-panel"><div className="panel-head"><div><div className="panel-kicker">ÖĞRENCİ TAKİBİ</div><h2>Öğrencilerin</h2><p>Aktif öğrenci ilerlemesi</p></div><button className="panel-link inline" onClick={onOpenStudents}>Tümünü gör <ArrowRight size={14}/></button></div><div className="student-table-wrap"><table className="student-table"><thead><tr><th>ÖĞRENCİ</th><th>HEDEF</th><th>İLERLEME</th><th>DURUM</th></tr></thead><tbody>{students.slice(0,4).map((s,i)=>{const progress=studentProgress(s);return <tr key={s.id}><td><div className="person-cell"><div className={`avatar avatar-${['peach','lavender','mint','butter'][i%4]}`}>{initials(s.full_name)}</div><div><strong>{s.full_name}</strong><span>{s.email||'PT öğrencisi'}</span></div></div></td><td><span className="goal-tag">{s.goal||'Genel sağlık'}</span></td><td><div className="progress-cell">{progress===null?<span className="muted">Ölçüm yok</span>:<><div className="progress-line"><i style={{width:`${progress}%`}}/></div><span>%{progress}</span></>}</div></td><td><span className={`status ${s.status==='active'?'status-active':s.status==='pending'?'status-pending':'status-inactive'}`}><i/>{s.status==='active'?'Aktif':s.status==='pending'?'Onay bekliyor':'Pasif'}</span></td></tr>})}</tbody></table>{!students.length&&<EmptyState text="Henüz öğrenci kaydı yok."/>}</div><div className="student-list-footer"><span><b>{activeStudents}</b> aktif öğrenci</span><button onClick={onOpenStudents}>Öğrenci yönetimine git <ArrowRight size={14}/></button></div><div className="coach-pulse"><div><span>Son 7 gün antrenman</span><strong>{weeklyWorkouts}</strong></div><div><span>Kaydedilen günlerde öğün uyumu</span><strong>{nutritionAdherence===null?'Veri yok':`${nutritionAdherence}%`}</strong></div><div><span>Yanıt bekleyen rapor</span><strong>{reportsToReview}</strong></div><div><span>Ölçüm bekleyen</span><strong>{measurementsDue}</strong></div></div></div>
   <div className="panel payments-panel"><div className="panel-head compact"><div><div className="panel-kicker">FİNANSAL DURUM</div><h2>Son ödemeler</h2></div><button className="icon-btn" onClick={onOpenFinances} aria-label="Finans sayfası"><ArrowRight size={17}/></button></div><div className="payments-total"><div><span>Toplam tahsilat</span><strong>{money(receivedTotal)}</strong></div><div className="total-icon"><CircleDollarSign size={20}/></div></div><div className="payment-list">{payments.slice(0,3).map(p=><div className="payment-row" key={p.id}><div className={`avatar avatar-${p.color||'mint'}`}>{p.initials||initials(p.name)}</div><div className="payment-person"><strong>{p.name}</strong><span>{p.description} · {p.date}</span></div><div className="payment-value"><strong>{money(p.amount)}</strong><span className={`payment-state ${p.status==='paid'?'paid':''}`}>{p.status==='paid'?'Ödendi':'Bekliyor'}</span></div></div>)}{!payments.length&&<EmptyState text="Henüz ödeme kaydı yok."/>}</div><button className="panel-link" onClick={onOpenFinances}>Finans özetini gör <ArrowRight size={14}/></button></div></section>
 </>
}
function StatCard({icon:Icon,label,value,note,tone}){return <article className="stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon ${tone}`}><Icon size={17}/></span></div><strong className="stat-value">{value}</strong><div className="stat-note">{note}</div></article>}
function AppointmentRow({item}){return <div className={`appointment-row ${item.status==='next'?'next':''}`}><div className="appointment-time">{item.time}</div><div className="appointment-track"><i/></div><div className={`avatar avatar-${item.color}`}>{item.initials}</div><div className="appointment-info"><strong>{item.name}</strong><span>{item.type}</span></div>{item.status==='completed'?<span className="done-mark"><Check size={13}/></span>:item.status==='next'?<span className="now-tag">SIRADAKİ</span>:<button className="icon-btn dots-btn" aria-label="Seans seçenekleri"><Ellipsis size={17}/></button>}</div>}
function StudentsPage({students,query,setQuery,onAdd,onApprove,onOpen}){return <div className="panel directory-panel"><div className="directory-head"><div><div className="panel-kicker">ÖĞRENCİ YÖNETİMİ</div><h2>Tüm öğrenciler <span>{students.length}</span></h2><p>Öğrenci kayıtlarını ve hedeflerini yönet.</p></div><button className="btn-primary" onClick={onAdd}><Plus size={17}/> Öğrenci ekle</button></div><div className="table-toolbar"><div className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="İsim, e-posta veya hedef ara…"/></div></div><div className="directory-table-wrap"><table className="student-table directory-table"><thead><tr><th>ÖĞRENCİ</th><th>YAŞ</th><th>BOY</th><th>GÜNCEL KİLO</th><th>HEDEF</th><th>BAŞLANGIÇ</th><th>HEDEF KİLO</th><th>KAYIT TARİHİ</th><th>DURUM</th><th></th></tr></thead><tbody>{students.map((s,i)=><tr key={s.id} onClick={()=>onOpen(s)}><td><div className="person-cell"><div className={`avatar avatar-${['peach','lavender','mint','butter'][i%4]}`}>{initials(s.full_name)}</div><div><strong>{s.full_name}</strong><span>{s.email||'E-posta eklenmedi'}</span></div></div></td><td>{ageOf(s.birth_date)===null?'—':`${ageOf(s.birth_date)} yaş`}</td><td>{s.height_cm?`${s.height_cm} cm`:'—'}</td><td>{s.current_weight_kg?`${s.current_weight_kg} kg`:s.start_weight?`${s.start_weight} kg`:'—'}</td><td><span className="goal-tag">{s.goal||'Genel sağlık'}</span></td><td>{s.start_weight?`${s.start_weight} kg`:'—'}</td><td>{s.target_weight?`${s.target_weight} kg`:'—'}</td><td>{fmtDate(s.joined_on)}</td><td><span className={`status ${s.status==='active'?'status-active':s.status==='pending'?'status-pending':'status-inactive'}`}><i/>{s.status==='active'?'Aktif':s.status==='pending'?'Onay bekliyor':'Pasif'}</span></td><td>{s.status==='pending'?<button className="btn-approve" onClick={e=>{e.stopPropagation();onApprove(s)}}><Check size={14}/> Onayla</button>:<button className="icon-btn" aria-label="Öğrenci işlemleri"><Ellipsis size={17}/></button>}</td></tr>)}</tbody></table>{students.length===0&&<EmptyState text={query?'Aramana uygun öğrenci bulunamadı.':'Henüz öğrenci yok. İlk kaydı ekleyerek başlayabilirsin.'}/>}</div><div className="table-bottom"><span>Toplam <strong>{students.length}</strong> öğrenci · <strong>{students.filter(s=>s.status==='pending').length}</strong> onay bekliyor</span><div><button className="page-btn" disabled><ChevronLeft size={15}/></button><button className="page-number">1</button><button className="page-btn" disabled><ChevronRight size={15}/></button></div></div></div>}
function ModulePage({page,students,appointments,payments,onAdd,onNotice,onOpenStudent,onUpdateAppointment,onUpdatePayment}){
 const info={Antrenman:{icon:Dumbbell,title:'Antrenman planları',desc:'Programları öğrenci profillerinden oluştur ve takip et.',empty:'Öğrencilerin için program oluştur.'},Beslenme:{icon:Apple,title:'Beslenme planları',desc:'Kalori, makro ve öğün planlarını öğrenci bazında yönet.',empty:'Beslenme planları öğrenci profillerinde görünür.'},Gelişim:{icon:Activity,title:'Gelişim takibi',desc:'Ölçüm geçmişi, vücut kompozisyonu ve fotoğraflar.',empty:'Ölçüm ve gelişim kayıtlarını profillerden yönet.'},Takvim:{icon:CalendarDays,title:'Seans takvimi',desc:'Planlanan ve tamamlanan PT seansları.',empty:'Henüz takvim kaydı yok.'},Finans:{icon:CircleDollarSign,title:'Finans ve ödemeler',desc:'Paket satışları, tahsilatlar ve bekleyen ödemeler.',empty:'Henüz finans kaydı yok.'}}[page]||{icon:Activity,title:page,desc:'',empty:'Bu modül için kayıt bulunamadı.'};const Icon=info.icon
 return <div className="panel module-panel"><div className="module-title"><div className={`module-icon tone-${page==='Finans'?'gold':page==='Beslenme'?'mint':'lavender'}`}><Icon size={21}/></div><div><div className="panel-kicker">EMRE AKKOYUN · PT</div><h2>{info.title}</h2><p>{info.desc}</p></div><button className="btn-primary" onClick={onAdd}><Plus size={16}/>{page==='Finans'?'Ödeme ekle':page==='Takvim'?'Seans planla':page==='Antrenman'?'Öğrenci planlarını aç':page==='Beslenme'?'Öğrenci planlarını aç':'Öğrencileri görüntüle'}</button></div>
 {page==='Takvim'?<div className="module-records">{appointments.length?appointments.map(a=><div className="module-record" key={a.id}><div className="appointment-time">{a.time}</div><div className="avatar avatar-peach">{a.initials}</div><div className="payment-person"><strong>{a.name}</strong><span>{a.date} · {a.type}{a.location?` · ${a.location}`:''}</span></div><span className={`status ${a.status==='completed'?'status-active':a.status==='scheduled'?'status-pending':'status-inactive'}`}><i/>{a.status==='completed'?'Tamamlandı':a.status==='scheduled'?'Planlandı':a.status==='cancelled'?'İptal':'Gelmedi'}</span>{a.status==='scheduled'&&<div className="module-actions"><button className="btn-quiet" onClick={()=>onUpdateAppointment(a,'completed')}>Tamamlandı</button><button className="text-link" onClick={()=>onUpdateAppointment(a,'cancelled')}>İptal et</button></div>}</div>):<div className="module-empty"><div className="empty-illustration"><Icon size={27}/></div><h3>{info.empty}</h3><button className="btn-primary" onClick={onAdd}><Plus size={15}/> Seans planla</button></div>}</div>:page==='Finans'?<div className="module-records">{payments.length?payments.map(p=><div className="module-record" key={p.id}><div className="avatar avatar-mint">{p.initials}</div><div className="payment-person"><strong>{p.name}</strong><span>{p.description} · {p.date}</span></div><div className="payment-value"><strong>{money(p.amount)}</strong><span className={`payment-state ${p.status==='paid'?'paid':''}`}>{p.status==='paid'?'Ödendi':p.status==='overdue'?'Gecikmiş':'Bekliyor'}</span></div>{p.status==='paid'?<button className="text-link" onClick={()=>onUpdatePayment(p,'pending')}>Bekliyor yap</button>:<button className="btn-quiet" onClick={()=>onUpdatePayment(p,'paid')}>Tahsil edildi</button>}</div>):<div className="module-empty"><div className="empty-illustration"><Icon size={27}/></div><h3>{info.empty}</h3><button className="btn-primary" onClick={onAdd}><Plus size={15}/> Ödeme ekle</button></div>}</div>:<div className="module-records">{students.length?students.map(student=><div className="module-record" key={student.id}><div className="avatar avatar-lavender">{initials(student.full_name)}</div><div className="payment-person"><strong>{student.full_name}</strong><span>{student.goal||'Hedef belirtilmedi'} · {student.status==='active'?'Aktif':student.status==='pending'?'Onay bekliyor':'Pasif'}</span></div><button className="btn-quiet" onClick={()=>onOpenStudent(student)}>Profili aç <ArrowRight size={14}/></button></div>):<div className="module-empty"><div className="empty-illustration"><Icon size={27}/></div><h3>{info.empty}</h3><button className="btn-primary" onClick={onAdd}><Plus size={15}/> Öğrencilere git</button></div>}</div>}
 </div>
}

function RecordModal({kind,students,onClose,onSave}){
 const [form,setForm]=useState({student_id:'',description:'PT paketi',amount:'',status:'pending',due_date:'',starts_at:'',ends_at:'',location:'',notes:''});const [saving,setSaving]=useState(false);const [error,setError]=useState('');const isAppointment=kind==='appointment'
 async function submit(e){e.preventDefault();setError('');if(!form.student_id){setError('Öğrenci seç.');return}if(isAppointment&&!form.starts_at){setError('Seans başlangıç tarihini gir.');return}if(!isAppointment&&(!form.amount||Number(form.amount)<0)){setError('Geçerli bir tutar gir.');return}setSaving(true);await onSave(form);setSaving(false)}
 return <div className="modal-scrim" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modal" onSubmit={submit}><div className="modal-head"><div><div className="panel-kicker">{isAppointment?'TAKVİM':'FİNANS'}</div><h2>{isAppointment?'Seans planla':'Ödeme kaydı ekle'}</h2><p>Kayıt seçilen öğrenci profiline bağlanır.</p></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Kapat"><X size={18}/></button></div><div className="form-grid"><label className="full-field">Öğrenci<select required value={form.student_id} onChange={e=>setForm(f=>({...f,student_id:e.target.value}))}><option value="">Öğrenci seç</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></label>{isAppointment?<><label>Başlangıç<input type="datetime-local" required value={form.starts_at} onChange={e=>setForm(f=>({...f,starts_at:e.target.value}))}/></label><label>Bitiş<input type="datetime-local" value={form.ends_at} onChange={e=>setForm(f=>({...f,ends_at:e.target.value}))}/></label><label>Konum<input value={form.location} onChange={e=>setForm(f=>({...f,location:e.target.value}))} placeholder="Stüdyo / çevrim içi"/></label><label className="full-field">Not<input value={form.notes} onChange={e=>setForm(f=>({...f,notes:e.target.value}))} placeholder="Seans türü veya not"/></label></>:<><label className="full-field">Açıklama<input required value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))}/></label><label>Tutar (₺)<input type="number" min="0" step="0.01" required value={form.amount} onChange={e=>setForm(f=>({...f,amount:e.target.value}))}/></label><label>Son ödeme tarihi<input type="date" value={form.due_date} onChange={e=>setForm(f=>({...f,due_date:e.target.value}))}/></label><label className="full-field">Durum<select value={form.status} onChange={e=>setForm(f=>({...f,status:e.target.value}))}><option value="pending">Bekliyor</option><option value="paid">Tahsil edildi</option><option value="overdue">Gecikmiş</option></select></label></>}</div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button className="btn-quiet" type="button" onClick={onClose}>Vazgeç</button><button className="btn-primary" disabled={saving||!students.length}>{saving?'Kaydediliyor…':isAppointment?'Seansı kaydet':'Ödeme kaydet'}</button></div></form></div>
}

function AddStudentModal({onClose,onSave}){const [form,setForm]=useState({full_name:'',email:'',phone:'',goal:'Yağ yakımı',start_weight:'',target_weight:''});const [saving,setSaving]=useState(false);function set(k,v){setForm(f=>({...f,[k]:v}))}async function submit(e){e.preventDefault();setSaving(true);await onSave({...form,start_weight:form.start_weight?Number(form.start_weight):null,target_weight:form.target_weight?Number(form.target_weight):null});setSaving(false)}return <div className="modal-scrim" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modal" onSubmit={submit}><div className="modal-head"><div><div className="panel-kicker">ÖĞRENCİ KAYDI</div><h2>Yeni öğrenci ekle</h2><p>Temel bilgileri gir, profilini daha sonra genişletebilirsin.</p></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Kapat"><X size={18}/></button></div><div className="form-grid"><label className="full-field">Ad soyad<input autoFocus required value={form.full_name} onChange={e=>set('full_name',e.target.value)} placeholder="Örn. Ayşe Yılmaz"/></label><label>E-posta<input type="email" value={form.email} onChange={e=>set('email',e.target.value)} placeholder="ornek@email.com"/></label><label>Telefon<input type="tel" value={form.phone} onChange={e=>set('phone',e.target.value)} placeholder="05XX XXX XX XX"/></label><label className="full-field">Ana hedef<select value={form.goal} onChange={e=>set('goal',e.target.value)}><option>Yağ yakımı</option><option>Kas kazanımı</option><option>Güç ve kondisyon</option><option>Genel sağlık</option><option>Esneklik ve mobilite</option></select></label><label>Başlangıç kilosu (kg)<input type="number" min="0" step="0.1" value={form.start_weight} onChange={e=>set('start_weight',e.target.value)} placeholder="70"/></label><label>Hedef kilosu (kg)<input type="number" min="0" step="0.1" value={form.target_weight} onChange={e=>set('target_weight',e.target.value)} placeholder="65"/></label></div><div className="modal-actions"><button className="btn-quiet" type="button" onClick={onClose}>Vazgeç</button><button className="btn-primary" disabled={saving}>{saving?'Kaydediliyor…':<><Plus size={16}/> Öğrenciyi kaydet</>}</button></div></form></div>}
function StudentView({user,profile,onSignOut}){
 const [student,setStudent]=useState(null);const [plans,setPlans]=useState([]);const [nutritionPlans,setNutritionPlans]=useState([]);const [measurements,setMeasurements]=useState([]);const [workoutLogs,setWorkoutLogs]=useState([]);const [nutritionLog,setNutritionLog]=useState(null);const [reports,setReports]=useState([]);const [studentPayments,setStudentPayments]=useState([]);const [studentAppointments,setStudentAppointments]=useState([]);const [exerciseResults,setExerciseResults]=useState({});const [mealChecks,setMealChecks]=useState([]);const [waterMl,setWaterMl]=useState('');const [report,setReport]=useState({weight_kg:'',energy_level:'',sleep_hours:'',workout_done:'',nutrition_adherence:'',notes:''});const [error,setError]=useState('');const [notice,setNotice]=useState('');const [saving,setSaving]=useState(false)
 const today=localDate()
 useEffect(()=>{let alive=true;(async()=>{const {data:st,error:e}=await supabase.from('students').select('*').eq('profile_id',user.id).single();if(!alive)return;if(e){setError(`Öğrenci profilin yüklenemedi: ${e.message}`);return}setStudent(st);if(st.status!=='active'||!st.profile_complete)return;const [w,n,m,wl,nl,r,pay,ap]=await Promise.all([supabase.from('workout_plans').select('*').eq('student_id',st.id).eq('active',true).order('created_at',{ascending:false}),supabase.from('nutrition_plans').select('*').eq('student_id',st.id).eq('active',true).order('created_at',{ascending:false}),supabase.from('measurements').select('*').eq('student_id',st.id).order('measured_on',{ascending:false}).limit(6),supabase.from('workout_logs').select('*').eq('student_id',st.id).order('completed_at',{ascending:false}).limit(20),supabase.from('nutrition_logs').select('*').eq('student_id',st.id).eq('logged_on',today).maybeSingle(),supabase.from('student_reports').select('*').eq('student_id',st.id).order('report_date',{ascending:false}).limit(5),supabase.from('payments').select('id,description,amount,status,due_date,paid_at,created_at').eq('student_id',st.id).order('created_at',{ascending:false}).limit(50),supabase.from('appointments').select('id,starts_at,ends_at,status,location,notes').eq('student_id',st.id).gte('starts_at',new Date(Date.now()-30*86400000).toISOString()).order('starts_at',{ascending:true}).limit(50)]);if(!alive)return;setPlans(w.data||[]);setNutritionPlans(n.data||[]);setMeasurements(m.data||[]);setWorkoutLogs(wl.data||[]);setNutritionLog(nl.data||null);setReports(r.data||[]);setStudentPayments(pay.data||[]);setStudentAppointments(ap.data||[]);if(nl.data){setMealChecks(nl.data.meals_completed||[]);setWaterMl(nl.data.water_ml||'')}})();return()=>{alive=false}},[user.id,today])
 const activeNutrition=nutritionPlans[0];const completedMealNames=nutritionLog?.meals_completed||[]
 async function finishWorkout(plan){setSaving(true);setError('');const existing=workoutLogs.find(x=>x.workout_plan_id===plan.id&&new Date(x.completed_at).toLocaleDateString('en-CA')===today);const payload={student_id:student.id,workout_plan_id:plan.id,completed_at:new Date().toISOString(),completed:true,exercise_results:(plan.exercises||[]).map((exercise,index)=>({name:exercise.name||exercise.exercise||`Hareket ${index+1}`,...(exerciseResults[`${plan.id}-${index}`]||{})}))};const res=existing?await supabase.from('workout_logs').update(payload).eq('id',existing.id).select().single():await supabase.from('workout_logs').insert(payload).select().single();if(res.error)setError(res.error.message);else{setWorkoutLogs(rows=>[res.data,...rows.filter(x=>x.id!==res.data.id)]);setNotice('Antrenman tamamlandı olarak kaydedildi.')}setSaving(false)}
 async function saveNutritionDay(e){e.preventDefault();if(!activeNutrition)return;setSaving(true);setError('');const consumed=(activeNutrition.meals||[]).filter((_,index)=>mealChecks.includes(String(index))).flatMap(item=>item.foods||[]).reduce((total,food)=>({calories:total.calories+Number(food.calories||0),protein:total.protein+Number(food.protein_g||0),carbs:total.carbs+Number(food.carbs_g||0),fat:total.fat+Number(food.fat_g||0)}),{calories:0,protein:0,carbs:0,fat:0});const payload={student_id:student.id,logged_on:today,calories:consumed.calories,protein_g:consumed.protein,carbs_g:consumed.carbs,fat_g:consumed.fat,water_ml:Number(waterMl)||0,meals_completed:mealChecks};const result=nutritionLog?await supabase.from('nutrition_logs').update(payload).eq('id',nutritionLog.id).select().single():await supabase.from('nutrition_logs').insert(payload).select().single();if(result.error)setError(result.error.message);else{setNutritionLog(result.data);setNotice('Günlük beslenme takibin kaydedildi.')}setSaving(false)}
 async function submitReport(e){e.preventDefault();setSaving(true);setError('');const payload={student_id:student.id,report_date:today,weight_kg:Number(report.weight_kg)||null,energy_level:Number(report.energy_level)||null,sleep_hours:Number(report.sleep_hours)||null,workout_done:report.workout_done===''?null:report.workout_done==='true',nutrition_adherence:Number(report.nutrition_adherence)||null,notes:report.notes.trim()||null};const {data,error}=await supabase.from('student_reports').insert(payload).select().single();if(error)setError(error.message);else{setReports(rows=>[data,...rows]);if(payload.weight_kg){const {data:measurement,error:measurementError}=await supabase.from('measurements').insert({student_id:student.id,measured_on:today,weight_kg:payload.weight_kg}).select().single();if(measurementError)setError(`Rapor gönderildi; kilo ölçümü kaydedilemedi: ${measurementError.message}`);else{setMeasurements(rows=>[measurement,...rows]);setStudent(current=>({...current,current_weight_kg:payload.weight_kg}))}}setReport({weight_kg:'',energy_level:'',sleep_hours:'',workout_done:'',nutrition_adherence:'',notes:''});setNotice('Haftalık raporun antrenörüne gönderildi.')}setSaving(false)}
 const weekWorkoutCount=workoutLogs.filter(x=>new Date(x.completed_at)>=new Date(Date.now()-7*86400000)&&x.completed).length
 return <div className="student-portal"><header className="portal-header"><div className="brand"><div className="brand-mark"><Activity size={20}/></div><div><strong>EMRE AKKOYUN</strong><span>ÖĞRENCİ PORTALI</span></div></div><button className="btn-quiet" onClick={onSignOut}><LogOut size={16}/> Çıkış yap</button></header><main className="portal-main"><div className="eyebrow">KİŞİSEL ALANIN</div><h1>Merhaba, {profile.full_name||user.email?.split('@')[0]} 👋</h1><p className="portal-lead">Antrenman yolculuğundaki gelişmeleri buradan takip et.</p>{notice&&<div className="form-info">{notice}</div>}{error&&<div className="form-error">{error}</div>}{!student?<div className="loading-screen"><span className="loader"/>Profilin yükleniyor…</div>:student.status!=='active'&&student.status!=='pending'?<div className="panel student-pending"><div className="panel-kicker">HESAP DURUMU</div><h2>Hesabın şu anda pasif</h2><p>Erişiminle ilgili bilgi için antrenörünle iletişime geç.</p></div>:!student.profile_complete?<StudentProfileSetup student={student} onSaved={setStudent}/>:student.status==='pending'?<div className="panel student-pending"><div className="pending-icon"><Clock3 size={23}/></div><div className="panel-kicker">KAYIT TAMAMLANDI</div><h2>Hoca onayı bekleniyor</h2><p>Öğrenci hesabın oluşturuldu. Emre seni aktif ettiğinde antrenman ve gelişim alanların açılacak.</p></div>:<><div className="portal-stats"><div className="panel"><span>Başlangıç kilosu</span><strong>{student.start_weight||'—'} <small>kg</small></strong></div><div className="panel"><span>Güncel kilo</span><strong>{measurements[0]?.weight_kg||student.current_weight_kg||'—'} <small>kg</small></strong></div><div className="panel"><span>Bu haftaki antrenman</span><strong>{weekWorkoutCount} <small>tamamlandı</small></strong></div></div><div className="portal-grid"><section className="panel"><div className="panel-head"><div><div className="panel-kicker">SEANS TAKVİMİ</div><h2>Seanslarım</h2></div></div>{studentAppointments.length?studentAppointments.map(item=><div className="portal-record-row" key={item.id}><div><strong>{new Date(item.starts_at).toLocaleDateString('tr-TR',{weekday:'short',day:'numeric',month:'short'})} · {new Date(item.starts_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}</strong><span>{item.notes||'PT seansı'}{item.location?` · ${item.location}`:''}</span></div><em>{item.status==='completed'?'Tamamlandı':item.status==='cancelled'?'İptal':item.status==='no_show'?'Katılmadı':'Planlandı'}</em></div>):<EmptyState text="Henüz seans planlanmadı."/>}</section><section className="panel"><div className="panel-head"><div><div className="panel-kicker">ÖDEME GEÇMİŞİ</div><h2>Ödemelerim</h2></div></div>{studentPayments.length?studentPayments.map(item=><div className="portal-record-row" key={item.id}><div><strong>{item.description} · {money(item.amount)}</strong><span>{item.due_date?`Son ödeme ${fmtDate(item.due_date)}`:'Tarih belirtilmedi'}</span></div><em>{item.status==='paid'?'Ödendi':item.status==='overdue'?'Gecikmiş':'Bekliyor'}</em></div>):<EmptyState text="Henüz ödeme kaydı yok."/>}</section></div><div className="portal-grid"><section className="panel"><div className="panel-head"><div><div className="panel-kicker">HAFTALIK PLANIN</div><h2>Antrenman programı</h2></div></div>{plans.length?plans.map(p=><article className="portal-workout" key={p.id}><div><Dumbbell size={18}/><strong>{p.title}</strong></div><p>{p.description||p.goal||'Kişisel antrenman planın'}</p>{Array.isArray(p.exercises)&&p.exercises.map((x,i)=>{const key=`${p.id}-${i}`,entry=exerciseResults[key]||{};return <div className="portal-exercise" key={key}><strong>{x.name||x.exercise||`Hareket ${i+1}`}</strong><span>Plan: {x.sets||'—'} set × {x.reps||'—'} · {x.weight_kg?`${x.weight_kg} kg`:''}</span><div className="portal-exercise-inputs"><label>Gerçek kilo<input type="number" step="0.5" value={entry.weight_kg||''} onChange={e=>setExerciseResults(o=>({...o,[key]:{...o[key],weight_kg:e.target.value?Number(e.target.value):null}}))}/></label><label>Tekrar<input type="number" value={entry.reps||''} onChange={e=>setExerciseResults(o=>({...o,[key]:{...o[key],reps:e.target.value?Number(e.target.value):null}}))}/></label><label>Tamamlanan set<input type="number" value={entry.completed_sets||''} onChange={e=>setExerciseResults(o=>({...o,[key]:{...o[key],completed_sets:e.target.value?Number(e.target.value):null}}))}/></label><label>Zorluk (1–10)<input type="number" min="1" max="10" value={entry.difficulty||''} onChange={e=>setExerciseResults(o=>({...o,[key]:{...o[key],difficulty:e.target.value?Number(e.target.value):null}}))}/></label><label className="full-field">Not<input value={entry.notes||''} onChange={e=>setExerciseResults(o=>({...o,[key]:{...o[key],notes:e.target.value}}))}/></label></div></div>})}<button className="btn-primary" disabled={saving} onClick={()=>finishWorkout(p)}><Check size={15}/>{workoutLogs.some(x=>x.workout_plan_id===p.id&&new Date(x.completed_at).toLocaleDateString('en-CA')===today)?'Bugünkü antrenmanı güncelle':'Antrenmanı tamamla'}</button></article>):<EmptyState text="Henüz aktif antrenman programı eklenmedi."/>}</section><section className="panel"><div className="panel-head"><div><div className="panel-kicker">SON ÖLÇÜMLER</div><h2>Gelişim geçmişi</h2></div></div>{measurements.length?measurements.map(m=><div className="measurement-row" key={m.id}><span>{fmtDate(m.measured_on)}</span><strong>{m.weight_kg?`${m.weight_kg} kg`:'Ölçüm'}</strong>{m.body_fat_pct!=null&&<em>%{m.body_fat_pct} yağ</em>}</div>):<EmptyState text="İlk ölçümün eklendiğinde burada görebilirsin."/>}</section></div><div className="portal-grid"><section className="panel"><div className="panel-head"><div><div className="panel-kicker">GÜNLÜK TAKİP</div><h2>Beslenme planın</h2></div></div>{activeNutrition?<form className="portal-nutrition" onSubmit={saveNutritionDay}><div className="macro-total">{activeNutrition.daily_calories||0} kcal · Protein {activeNutrition.protein_g||0} g · Karbonhidrat {activeNutrition.carbs_g||0} g · Yağ {activeNutrition.fat_g||0} g</div>{(activeNutrition.meals||[]).map((item,i)=><label className="meal-check" key={`${item.name}-${i}`}><input type="checkbox" checked={mealChecks.includes(String(i))} onChange={e=>setMealChecks(old=>e.target.checked?[...new Set([...old,String(i)])]:old.filter(index=>index!==String(i)))}/><span><strong>{item.name}</strong><small>{(item.foods||[]).map(f=>`${f.name}${f.grams?` · ${f.grams} g`:''}`).join(', ')}</small></span><em>{mealChecks.includes(String(i))?'Tamamlandı':'Bekliyor'}</em></label>)}<label>Su tüketimi (ml)<input type="number" min="0" step="100" value={waterMl} onChange={e=>setWaterMl(e.target.value)} placeholder={`Hedef: ${activeNutrition.water_target_ml||'—'} ml`}/></label><button className="btn-primary" disabled={saving}><Save size={15}/>Bugünkü takibi kaydet</button></form>:<EmptyState text="Henüz aktif beslenme planı yok."/>}</section><section className="panel"><div className="panel-head"><div><div className="panel-kicker">HAFTALIK GERİ BİLDİRİM</div><h2>Hoca için rapor gönder</h2></div></div><form className="portal-report" onSubmit={submitReport}><div className="form-grid"><label>Güncel kilo (kg)<input type="number" step="0.1" value={report.weight_kg} onChange={e=>setReport(o=>({...o,weight_kg:e.target.value}))}/></label><label>Enerji (1–5)<input type="number" min="1" max="5" value={report.energy_level} onChange={e=>setReport(o=>({...o,energy_level:e.target.value}))}/></label><label>Uyku (saat)<input type="number" step="0.5" min="0" max="24" value={report.sleep_hours} onChange={e=>setReport(o=>({...o,sleep_hours:e.target.value}))}/></label><label>Beslenme uyumu (1–5)<input type="number" min="1" max="5" value={report.nutrition_adherence} onChange={e=>setReport(o=>({...o,nutrition_adherence:e.target.value}))}/></label><label>Antrenman yaptın mı?<select value={report.workout_done} onChange={e=>setReport(o=>({...o,workout_done:e.target.value}))}><option value="">Seçiniz</option><option value="true">Evet</option><option value="false">Hayır</option></select></label><label className="full-field">Not<textarea rows="3" value={report.notes} onChange={e=>setReport(o=>({...o,notes:e.target.value}))} placeholder="Bu hafta nasıl geçti?"/></label></div><button className="btn-primary" disabled={saving}><FileText size={15}/>Raporu gönder</button></form>{reports.length>0&&<div className="portal-report-history"><strong>Önceki raporların</strong>{reports.map(item=><div key={item.id}>{fmtDate(item.report_date)} · {item.coach_feedback?'Hoca yanıtladı':'Değerlendirme bekliyor'}</div>)}</div>}</section></div></>}</main></div>
}

function StudentProfileSetup({student,onSaved}){
 const [form,setForm]=useState({phone:student.phone||'',birth_date:student.birth_date||'',gender:student.gender||'',height_cm:student.height_cm||'',start_weight:student.start_weight||'',target_weight:student.target_weight||'',goal:student.goal||'',activity_level:student.activity_level||'',training_history:student.training_history||''});const [consented,setConsented]=useState(false);const [working,setWorking]=useState(false);const [error,setError]=useState('')
 function set(key,value){setForm(current=>({...current,[key]:value}))}
 async function submit(e){e.preventDefault();setError('');if(!consented){setError('Ölçüm ve hedef bilgilerinin koçunla paylaşılmasını onaylamalısın.');return}setWorking(true);const payload={...form,height_cm:form.height_cm?Number(form.height_cm):null,start_weight:form.start_weight?Number(form.start_weight):null,current_weight_kg:form.start_weight?Number(form.start_weight):null,target_weight:form.target_weight?Number(form.target_weight):null,profile_complete:true,privacy_consented_at:new Date().toISOString()};const {data,error:updateError}=await supabase.from('students').update(payload).eq('id',student.id).select().single();if(updateError)setError(updateError.message);else onSaved(data);setWorking(false)}
 return <form className="panel student-onboarding" onSubmit={submit}><div className="panel-kicker">PROFİLİNİ TAMAMLA</div><h2>Sana uygun plan için birkaç bilgi</h2><p>Bu bilgiler yalnızca antrenörünle paylaşılır. Sağlık ve sakatlık bilgisi girmiyoruz.</p><div className="form-grid"><label>Telefon<input type="tel" value={form.phone} onChange={e=>set('phone',e.target.value)} placeholder="05XX XXX XX XX"/></label><label>Doğum tarihi<input type="date" value={form.birth_date} onChange={e=>set('birth_date',e.target.value)}/></label><label>Cinsiyet<select value={form.gender} onChange={e=>set('gender',e.target.value)}><option value="">Belirtmek istemiyorum</option><option value="female">Kadın</option><option value="male">Erkek</option><option value="other">Diğer</option></select></label><label>Boy (cm)<input type="number" min="80" max="250" step="0.1" value={form.height_cm} onChange={e=>set('height_cm',e.target.value)}/></label><label>Başlangıç kilosu (kg)<input type="number" min="20" max="400" step="0.1" value={form.start_weight} onChange={e=>set('start_weight',e.target.value)}/></label><label>Hedef kilosu (kg)<input type="number" min="20" max="400" step="0.1" value={form.target_weight} onChange={e=>set('target_weight',e.target.value)}/></label><label>Ana hedef<input value={form.goal} onChange={e=>set('goal',e.target.value)} placeholder="Örn. güçlenme"/></label><label className="full-field">Günlük aktivite<select value={form.activity_level} onChange={e=>set('activity_level',e.target.value)}><option value="">Seçiniz</option><option value="low">Düşük</option><option value="moderate">Orta</option><option value="high">Yüksek</option></select></label><label className="full-field">Antrenman geçmişi<textarea value={form.training_history} onChange={e=>set('training_history',e.target.value)} rows={3} placeholder="Varsa önceki deneyimini kısaca anlat"/></label></div><label className="consent-check"><input type="checkbox" checked={consented} onChange={e=>setConsented(e.target.checked)}/> İletişim, profil, boy/kilo, hedef ve antrenman geçmişi bilgilerimin antrenörüm tarafından kullanılmasını kabul ediyorum.</label>{error&&<div className="form-error">{error}</div>}<button className="btn-primary" disabled={working}>{working?'Kaydediliyor…':'Profili tamamla'}</button></form>
}
function EmptyState({text}){return <div className="empty-state"><div><FileText size={18}/></div><span>{text}</span></div>}
